public int knapsack(int[] weight, int[] value, int W) {
    return solve(weight, value, weight.length - 1, W);
}

private int solve(int[] weight, int[] value, int i, int w) {
    if (i < 0) {
        return 0;
    }
    int skip = solve(weight, value, i - 1, w);
    int take = 0;
    if (weight[i] <= w) {
        take = value[i] + solve(weight, value, i - 1, w - weight[i]);
    }
    return Math.max(skip, take);
}

