public int knapsack(int[] weight, int[] value, int W) {
    int n = weight.length;
    int[][] memo = new int[n][W + 1];
    for (int[] row : memo) {
        Arrays.fill(row, -1);
    }
    return solve(weight, value, n - 1, W, memo);
}

private int solve(int[] weight, int[] value, int i, int w, int[][] memo) {
    if (i < 0) {
        return 0;
    }
    if (memo[i][w] != -1) {
        return memo[i][w];
    }
    int skip = solve(weight, value, i - 1, w, memo);
    int take = 0;
    if (weight[i] <= w) {
        take = value[i] + solve(weight, value, i - 1, w - weight[i], memo);
    }
    memo[i][w] = Math.max(skip, take);
    return memo[i][w];
}

