def knapsack(self, weight: list[int], value: list[int], W: int) -> int:
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def solve(i: int, w: int) -> int:
        if i < 0:
            return 0
        skip = solve(i - 1, w)
        take = 0
        if weight[i] <= w:
            take = value[i] + solve(i - 1, w - weight[i])
        return max(skip, take)

    return solve(len(weight) - 1, W)

