public int knapsack(int[] weight, int[] value, int W) {
    int n = weight.length;
    int[][] dp = new int[n + 1][W + 1];
    for (int i = 1; i <= n; i++) {
        int wt = weight[i - 1];
        int val = value[i - 1];
        for (int w = 0; w <= W; w++) {
            dp[i][w] = dp[i - 1][w];
            if (wt <= w) {
                dp[i][w] = Math.max(dp[i][w], val + dp[i - 1][w - wt]);
            }
        }
    }
    return dp[n][W];
}

// 1-D space-optimized: weight loop runs DESCENDING
public int knapsackOptimized(int[] weight, int[] value, int W) {
    int[] dp = new int[W + 1];
    for (int i = 0; i < weight.length; i++) {
        for (int w = W; w >= weight[i]; w--) {
            dp[w] = Math.max(dp[w], value[i] + dp[w - weight[i]]);
        }
    }
    return dp[W];
}

