def knapsack(self, weight: list[int], value: list[int], W: int) -> int:
    n = len(weight)
    dp = [[0] * (W + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        wt, val = weight[i - 1], value[i - 1]
        for w in range(W + 1):
            dp[i][w] = dp[i - 1][w]
            if wt <= w:
                dp[i][w] = max(dp[i][w], val + dp[i - 1][w - wt])
    return dp[n][W]

# 1-D space-optimized: weight loop runs DESCENDING
def knapsack_optimized(self, weight: list[int], value: list[int], W: int) -> int:
    dp = [0] * (W + 1)
    for i in range(len(weight)):
        for w in range(W, weight[i] - 1, -1):
            dp[w] = max(dp[w], value[i] + dp[w - weight[i]])
    return dp[W]

